// Independent addition-only RUP checker and residual entailment audit.
#include <bits/stdc++.h>
using namespace std;using C=vector<int>;using Clock=chrono::steady_clock;
struct Checker{int n;vector<C> db;vector<vector<int>> occ;vector<int> units,counts,stamp;set<C> known;bool empty=false;int gen=0;long long ops=0;Clock::time_point deadline;
 Checker(int n):n(n),occ(2*n+1) {deadline=Clock::now()+chrono::seconds(5);}
 void guard(){if((++ops&8191)==0&&Clock::now()>deadline)throw runtime_error("AUDIT_LIMIT");}
 C canon(C c){for(int l:c)if(!l||l>n||l< -n)throw runtime_error("invalid literal");sort(c.begin(),c.end());c.erase(unique(c.begin(),c.end()),c.end());return c;}
 bool taut(const C& c){for(int l:c)if(binary_search(c.begin(),c.end(),-l))return true;return false;}
 void add(C c){c=canon(move(c));if(taut(c)||!known.insert(c).second)return;int id=db.size();if(c.empty())empty=true;if(c.size()==1)units.push_back(c[0]);for(int l:c)occ[l+n].push_back(id);db.push_back(move(c));counts.push_back(0);stamp.push_back(0);}
 bool rup(const C& c){if(empty||taut(c)||known.count(c))return true;gen++;vector<int8_t>a(n+1,0);C q;auto put=[&](int l){int s=l>0?1:-1;int v=abs(l);if(a[v])return a[v]==s;a[v]=s;q.push_back(l);return true;};for(int l:c)if(!put(-l))return true;for(int l:units)if(!put(l))return true;
  for(size_t i=0;i<q.size();i++){int l=q[i];for(int id:occ[n-l]){guard();if(stamp[id]!=gen){stamp[id]=gen;counts[id]=0;}int k=++counts[id];auto&cl=db[id];if(k==(int)cl.size())return true;if(k==(int)cl.size()-1){int remaining=0,num=0;for(int x:cl)if(a[abs(x)]!=(x>0?-1:1)){remaining=x;num++;}if(!num)return true;if(num==1&&!put(remaining))return true;}}}return false;}
};
C linecl(const string& line){istringstream s(line);int l;C c;while(s>>l){if(!l){string trailing;if(s>>trailing)throw runtime_error("trailing token");return c;}c.push_back(l);}throw runtime_error("unterminated clause");}
int main(int argc,char**argv){bool prefixonly=argc==5&&string(argv[3])=="--prefix";if(argc!=3&&!prefixonly)return 2;try{ifstream f(argv[1]);string line;int n=-1,m=-1;vector<C> source;C c;while(getline(f,line)){istringstream s(line);string t;s>>t;if(t.empty()||t=="c")continue;if(t=="%")break;if(t=="p"){string fmt;s>>fmt>>n>>m;if(fmt!="cnf"||n<0||n>10000||m<0)throw runtime_error("header");continue;}s.clear();s.str(line);int l;while(s>>l){if(l)c.push_back(l);else{source.push_back(c);c.clear();}}}if(n<0||(int)source.size()!=m||!c.empty())throw runtime_error("source size");Checker chk(n);for(auto&d:source)chk.add(d);ifstream p(argv[2]);if(!getline(p,line))throw runtime_error("empty proof");bool symbolic=line=="g11-symbolic-v1";long long prefix=0,res=0;bool lastempty=false;
 if(!symbolic){C z=chk.canon(linecl(line));if(!chk.rup(z))throw runtime_error("RUP line 1");chk.add(z);lastempty=z.empty();prefix++;}
 bool residual=false,order=false;while(getline(p,line)){chk.guard();if(symbolic&&line=="r"&&!residual){residual=true;continue;}if(symbolic&&residual&&line.rfind("o ",0)==0){C ord=linecl(line.substr(2));C s=ord;sort(s.begin(),s.end());if((int)s.size()!=n)throw runtime_error("order size");for(int i=0;i<n;i++)if(s[i]!=i+1)throw runtime_error("order permutation");order=true;break;}C z=chk.canon(linecl(line));if(residual){if(!chk.known.count(z)&&!chk.taut(z))throw runtime_error("residual clause missing from proven ledger");res++;}else{if(!chk.rup(z))throw runtime_error("invalid RUP line "+to_string(prefix+1));chk.add(z);lastempty=z.empty();prefix++;}}
 if(symbolic){if(!residual||!order||getline(p,line))throw runtime_error("malformed symbolic certificate");}else if(!lastempty&&!prefixonly)throw runtime_error("no empty clause");if(prefixonly){if(symbolic)throw runtime_error("prefix must be RUP only");ifstream msg(argv[4]);if(!msg)throw runtime_error("message file");int count=0;while(getline(msg,line)){chk.guard();C z=chk.canon(linecl(line));if(!chk.known.count(z))throw runtime_error("unproven feedback message");count++;}if(!count)throw runtime_error("no feedback messages");}cout<<"VERIFIED prefix="<<prefix<<" residual="<<res<<'\n';return 0;}catch(exception&e){cerr<<e.what()<<'\n';return string(e.what())=="AUDIT_LIMIT"?3:1;}}
